import leftTrim from 'left-trim';
leftTrim('  hello');        // 'hello'
leftTrim('//path', '/');  // 'path'

import {router} from 'tinyrouter';
const r = router([['/users/:id', showUser], ['/files/*', serveFile]]);
r.match('/users/42'); // {handler: showUser, params: {id: '42'}}

import {Atlas} from 'atlas-sdk';
const world = await Atlas.connect('http://localhost:7000').world({seed: 42});
await world.step(100);
console.log(await world.machine('alice-mac').screen());

import {clock} from 'deterministic-clock';
clock.install();
setTimeout(() => console.log('fired'), 1000);
clock.advance(1000); // prints 'fired'

import {diff, apply} from 'json-diff-lite';
const patch = diff({a: 1}, {a: 2, b: 3});
// [{op: 'replace', path: '/a', value: 2}, {op: 'add', path: '/b', value: 3}]
apply({a: 1}, patch); // {a: 2, b: 3}

import {EventBus} from 'eventbus-ts';
const bus = new EventBus<{tick: number; halt: void}>();
bus.on('tick', (n) => console.log(n));
bus.emit('tick', 1);

import {z} from 'zod-lite';
const User = z.object({id: z.number(), name: z.string()});
type User = z.infer<typeof User>;
User.parse({id: 1, name: 'alice'});

import {TokenBucket} from 'tokenbucket';
const limiter = new TokenBucket({capacity: 10, refillPerSecond: 2});
if (limiter.take(1)) send();

import {satisfies, compare} from 'semver-tiny';
satisfies('1.4.2', '^1.2.0'); // true
compare('2.0.0-beta.1', '2.0.0'); // -1

import spinner from 'cli-spinner-lite';
const s = spinner('Installing').start();
await install();
s.succeed('Installed 12 packages');
